// Predefined Function
// Gets a pointer to a valid UObject of type UEngine

class UEngine* UEngine::GetEngine()
{
        static UEngine* GEngine = nullptr;

        if (GEngine)
                return GEngine;
        
        /* Mini-dumper: read the engine's GEngine global directly. The
           original generated implementation walked ALL GObjects entries
           calling IsA(UEngine::StaticClass()) on each — the same array
           walk that crashed the GameThread from background threads. */
        if (Offsets::GEngine != 0)
                GEngine = *reinterpret_cast<UEngine**>(InSDKUtils::GetImageBase() + Offsets::GEngine);

        return GEngine; 
}


// Predefined Function
// Returns the result of UEngine::GetEngine() without a type-check, might be dangerous

class UGameEngine* UGameEngine::GetEngine()
{
        return static_cast<UGameEngine*>(UEngine::GetEngine());
}


